  [Test]
  [Category("Unit")]
  public void AcceptsTheMjpbTagIgnoringCase() {
    Assert.That(MjpegBVideoDecoder.Accepts(_Stream()), Is.True);
    Assert.That(MjpegBVideoDecoder.Accepts(_Stream(CodecTag.FromCharacters("MJPB"))), Is.True);
  }

  [Test]
  [Category("Unit")]
  public void RefusesAnythingElse() => Assert.That(MjpegBVideoDecoder.Accepts(_Stream(CodecTag.FromCharacters("mjpg"))), Is.False);

  [Test]
  [Category("Unit")]
  public void DecodesASingleFieldPacketAsAWholePicture() {
    var decoder = MjpegBVideoDecoder.Create(_Stream());

    var ok = decoder.TryDecode(new(0, _OneField), out var frame);

    Assert.That(ok, Is.True);
    Assert.That(frame.Width, Is.EqualTo(8));
    Assert.That(frame.Height, Is.EqualTo(8));
    for (var i = 0; i < frame.PixelData.Length; i += 3)
      Assert.That(frame.PixelData[i..(i + 3)], Is.EqualTo(new byte[] { 0xFE, 0x00, 0x00 }), $"pixel at byte {i}");
  }

  [Test]
  [Category("Unit")]
  public void WeavesTwoFieldsTopFieldFirst() {
    var decoder = MjpegBVideoDecoder.Create(_Stream());

    var ok = decoder.TryDecode(new(0, _TwoFields), out var frame);

    Assert.That(ok, Is.True);
    Assert.That(frame.Width, Is.EqualTo(8));
    Assert.That(frame.Height, Is.EqualTo(16));

    var stride = 8 * 3;
    for (var y = 0; y < 16; ++y) {
      var expected = y % 2 == 0 ? new byte[] { 0xFE, 0x00, 0x00 } : new byte[] { 0x00, 0x00, 0xFE };
      for (var x = 0; x < 8; ++x)
        Assert.That(frame.PixelData[(y * stride + x * 3)..(y * stride + x * 3 + 3)], Is.EqualTo(expected), $"pixel at row {y} column {x}");
    }
  }

  [Test]
  [Category("Unit")]
  public void RefusesAPacketTooShortForTheFieldHeader() {
    var decoder = MjpegBVideoDecoder.Create(_Stream());

    var failure = Assert.Throws<InvalidDataException>(() => decoder.TryDecode(new(0, _OneField[..10]), out _));
    Assert.That(failure!.Message, Does.Contain("48"));
  }

  [Test]
  [Category("Unit")]
  public void RefusesAFieldHeaderWhoseTagIsNotMjpg() {
    var patched = (byte[])_OneField.Clone();
    patched[4] = (byte)'x';
    var decoder = MjpegBVideoDecoder.Create(_Stream());

    var failure = Assert.Throws<InvalidDataException>(() => decoder.TryDecode(new(0, patched), out _));
    Assert.That(failure!.Message, Does.Contain("mjpg"));
  }

  [Test]
  [Category("Unit")]
  public void RefusesFieldsThatDisagreeOnSize() {
    var decoder = MjpegBVideoDecoder.Create(_Stream());

    var failure = Assert.Throws<InvalidDataException>(() => decoder.TryDecode(new(0, _MismatchedFieldSizes), out _));
    Assert.That(failure!.Message, Does.Contain("8x8"));
    Assert.That(failure!.Message, Does.Contain("4x4"));
  }

  [Test]
  [Category("Unit")]
  public void RefusesASecondFieldThatNamesAThird() {
    var decoder = MjpegBVideoDecoder.Create(_Stream());

    var failure = Assert.Throws<InvalidDataException>(() => decoder.TryDecode(new(0, _ThirdFieldNamed), out _));
    Assert.That(failure!.Message, Does.Contain("third field"));
  }
}
